css:
@font-face { font-family: "GEICO Roobert Heavy"; src: url("assets/GEICORoobert-Heavy.otf") format("opentype"); font-weight: 900; font-style: normal; font-display: swap; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"],
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .dyn-fit-stage,
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .board { background: var(--background, #004b9b); }
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .board {
  position: absolute;
  inset: 0;
  container-type: size;
  overflow: hidden;
  color: #fff;
  font-family: "GEICO Roobert Heavy", "Arial Black", sans-serif;
  font-weight: 900;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .stage {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 18cqh;
  overflow: hidden;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .glyph-slot {
  position: absolute;
  z-index: 1;
  left: 0;
  bottom: 0;
  height: 100%;
  aspect-ratio: 2592 / 1728;
  pointer-events: none;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .glyph {
  width: 100%;
  height: 100%;
  background-position: left bottom;
  background-repeat: no-repeat;
  background-size: 100% 100%;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .copy {
  position: absolute;
  z-index: 3;
  left: 16cqw;
  right: 27cqw;
  top: 6cqh;
  bottom: 3cqh;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  text-align: left;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .racer,
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .from {
  margin: 0;
  color: var(--secondary, #ffffff);
  font-family: Caveat, cursive;
  font-weight: 700;
  line-height: 0.95;
  max-width: 100%;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .racer { font-size: 12cqw; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .from {
  font-size: 8.2cqw;
  margin-top: 0.12em;
  text-align: right;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .from::before { content: "\2014\00a0"; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .sign {
  margin: 0.06em 0 0;
  color: var(--primary, #c8f546);
  font-family: "GEICO Roobert Heavy", "Arial Black", sans-serif;
  font-weight: 900;
  font-size: 9.2cqw;
  line-height: 0.92;
  letter-spacing: -0.02em;
  max-width: 100%;
  text-align: center;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .guest {
  position: absolute;
  z-index: 4;
  top: 50%;
  right: 3.2cqw;
  width: 20cqw;
  aspect-ratio: 3 / 4;
  object-fit: cover;
  border: 0;
  border-radius: 1.1cqw;
  background: transparent;
  transform: translateY(-50%) rotate(5deg);
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .foot {
  position: absolute;
  z-index: 5;
  left: 0;
  right: 0;
  bottom: 0;
  height: 18cqh;
  display: flex;
  align-items: center;
  gap: 2.4cqw;
  padding: 0 3.2cqw;
  background: #9fd4f0;
  border-top: 0.55cqh solid #c8f546;
  box-sizing: border-box;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .qr-box {
  flex: 0 0 auto;
  height: 74%;
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.45cqw;
  border-radius: 0.9cqw;
  background: #fff;
  box-sizing: border-box;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .qr-box img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .scan {
  flex: 1;
  margin: 0;
  text-align: center;
  color: #0c326e;
  font-family: "GEICO Roobert Heavy", "Arial Black", sans-serif;
  font-weight: 900;
  font-size: 3.5cqw;
  letter-spacing: -0.02em;
  line-height: 1;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .logo {
  flex: 0 0 16cqw;
  height: 3.4cqh;
  background: #0c326e;
  -webkit-mask: url("assets/geico-signs-logo.svg") center / contain no-repeat;
  mask: url("assets/geico-signs-logo.svg") center / contain no-repeat;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .swap {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.7s cubic-bezier(0.4, 0, 0.2, 1);
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"].on .swap { opacity: 1; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"].on .swap.is-out { opacity: 0; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .slot-logo,
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .slot-qr { display: none; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"].dyn-show-logo .slot-logo {
  display: block;
  position: absolute;
  z-index: 6;
  top: 4cqh;
  left: 4cqw;
  width: 14cqw;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"].dyn-show-qr .slot-qr {
  display: block;
  position: absolute;
  z-index: 6;
  right: 3cqw;
  bottom: 22cqh;
  width: 12cqw;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"].no-racer .racer,
#dyn-message-theme[data-theme="message-geico-marathon-signs"].no-name .from { display: none; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .guest:not([src]),
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .guest[src=""],
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .qr-box img:not([src]),
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .qr-box img[src=""] { display: none !important; }
#dyn-message-theme[data-theme="message-geico-marathon-signs"] img:not(.guest) {
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .guest[src] {
  display: block !important;
  visibility: visible !important;
  pointer-events: auto !important;
}
#dyn-message-theme[data-theme="message-geico-marathon-signs"] .qr-box img[src] {
  display: block !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
}
